package com.milktea.security;
import com.milktea.user.repository.NguoiDungRepository; import io.jsonwebtoken.JwtException; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; private final NguoiDungRepository users; public JwtFilter(JwtService jwt,NguoiDungRepository users){this.jwt=jwt;this.users=users;} @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{String username=jwt.claims(h.substring(7)).getSubject();users.findByTenDangNhap(username).filter(u->u.isDangHoatDong()).ifPresent(u->{UserPrincipal p=UserPrincipal.from(u); SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(p,null,p.getAuthorities()));});}catch(JwtException ignored){}chain.doFilter(req,res);} }
